using System.Net;using System.Net.Http;using System.Reflection;using TownOfHost;using TownOfHost.Modules;
partial class Program {
static int streamNumber;static BindingFlags flags=BindingFlags.Static|BindingFlags.NonPublic;
static void ResetStream(){StreamerInfo.DisconnectInternal();WaitFetch();YouTubeOfficialRuntime.ParticipationPolicyReviewed=true;YouTubeOfficialRuntime.Factory=()=>new OfficialYouTubeChatSource(new MissingYouTubeCredentials());TownOfHost.Main.ShowStreamComments.Value=false;TownOfHost.Main.JoinWord.Value="join:";TownOfHost.Main.RemoveWord.Value="withdraw";YouTubeMapVote.Enabled=new(){Value=false};ExtraFeatureOptions.JoinByCommentOnly=new(){Value=false};AmongUsClient.Instance??=new();AmongUsClient.Instance.AmHost=true;TownOfHost.GameStates.IsLobby=true;TownOfHost.GameStates.InGame=false;TownOfHost.Logger.Warnings.Clear();TownOfHost.Logger.Logs.Clear();StreamerInfo.TrySetStreamURL("https://youtu.be/"+(++streamNumber).ToString("D11"));}
static void Drain()=>typeof(StreamerInfo).GetMethod("DrainComments",flags).Invoke(null,null);
static void Queue(StreamerInfo info,string id,string channel,string text,bool live=true,string name="Viewer")=>typeof(StreamerInfo).GetMethod("Queue",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(info,new object[]{new[]{new LiveStreamComment(id,channel,name,text)},live});
static (StreamerInfo info,FakeSource handler) FakeStream(){int epoch=(int)typeof(StreamerInfo).GetField("epoch",flags).GetValue(null);var handler=new FakeSource();YouTubeOfficialRuntime.Factory=()=>handler;var info=(StreamerInfo)Activator.CreateInstance(typeof(StreamerInfo),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{"AbCdef12_-3",epoch},null);typeof(StreamerInfo).GetField("current",flags).SetValue(null,info);return(info,handler);}
sealed class FakeSource:IYouTubeChatSource {internal bool Disposed,Hang,RotateOnce;internal int Calls;internal YouTubeFailure? Failure;internal readonly List<string> Paths=new();internal YouTubeChatBatch[] Batches=Array.Empty<YouTubeChatBatch>();internal TaskCompletionSource<bool> Release;public async Task RunAsync(string video,Action<YouTubeChatBatch> receive,CancellationToken ct){Calls++;Paths.Add("mock-only");if(RotateOnce&&Calls==1)return;if(Release!=null)await Release.Task.WaitAsync(ct);if(Failure.HasValue)throw new YouTubeApiException(Failure.Value);foreach(var b in Batches)receive(b);if(Hang)await Task.Delay(Timeout.Infinite,ct);}public void Dispose()=>Disposed=true;}
static void RunLifecycle(){
Test("stream URL canonical removes tracking",()=>{ResetStream();Check(StreamerInfo.TrySetStreamURL("https://youtu.be/AbCdef12_-3?si=tracking")&&StreamerInfo.StreamURL=="https://www.youtube.com/watch?v=AbCdef12_-3"&&TownOfHost.Main.StreamURLConfig.Value==StreamerInfo.StreamURL);});
Test("invalid URL preserves existing selection",()=>{var old=StreamerInfo.StreamURL;Check(!StreamerInfo.TrySetStreamURL("https://evil.example/live")&&old==StreamerInfo.StreamURL);});
Test("no admission APIs remain",()=>{foreach(var method in new[]{"JoinPlayer","LeftPlayer","ChangeList"})Check(typeof(StreamerInfo).GetMethod(method)==null);});
Test("retired join-only flag cannot start requests",()=>{ResetStream();ExtraFeatureOptions.JoinByCommentOnly.Value=true;var(i,h)=FakeStream();StreamerInfo.CommentFrameTick(.02f);Check(h.Disposed&&h.Calls==0);});
Test("duplicate display and channel intake bounded",()=>{ResetStream();StreamerInfo.StartInterestReception();var(i,h)=FakeStream();Queue(i,"1","a","join:");Queue(i,"1","a","join:");Drain();Check(StreamerInfo.RecentComments.Count==1&&StreamerInfo.Interests.Count==1);});
Test("withdraw changes only display list",()=>{Queue((StreamerInfo)typeof(StreamerInfo).GetField("current",flags).GetValue(null),"2","a","withdraw");Drain();Check(StreamerInfo.Interests.Count==0);});
Test("nonhost sees comments without intake",()=>{ResetStream();AmongUsClient.Instance.AmHost=false;var(i,h)=FakeStream();Queue(i,"1","a","join:");Drain();Check(StreamerInfo.RecentComments.Count==1&&StreamerInfo.Interests.Count==0);});
Test("URL change drops obsolete worker queue",()=>{ResetStream();var(i,h)=FakeStream();StreamerInfo.TrySetStreamURL("https://youtu.be/zzzzzzzzzzz");Queue(i,"1","a","hello");Drain();Check(StreamerInfo.RecentComments.Count==0&&h.Disposed);});
Test("display retains at most thirty messages",()=>{ResetStream();var(i,h)=FakeStream();for(int n=0;n<300;n++)Queue(i,n.ToString(),"a","hello");Drain();Drain();Check(StreamerInfo.RecentComments.Count==30);});
Test("queue overflow reports bounded failure",()=>{ResetStream();var(i,h)=FakeStream();bool denied=false;try{for(int n=0;n<600;n++)Queue(i,n.ToString(),"a","hello");}catch(TargetInvocationException e)when(e.InnerException is YouTubeApiException a&&a.Reason==YouTubeFailure.BufferOverflow){denied=true;}Check(denied);});
Test("one persistent stream despite repeated ticks",()=>{ResetStream();var(i,h)=FakeStream();h.Hang=true;TownOfHost.Main.ShowStreamComments.Value=true;for(int n=0;n<200;n++)StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>h.Calls==1,2000));StreamerInfo.StopNetwork();WaitFetch();Check(h.Calls==1);});
Test("OFF discards pending comments and performs zero requests",()=>{ResetStream();var(i,h)=FakeStream();Queue(i,"1","a","hello");StreamerInfo.CommentFrameTick(.02f);Check(h.Calls==0&&h.Disposed&&StreamerInfo.RecentComments.Count==0);});
Test("disconnect clears interest and recent personal data",()=>{ResetStream();StreamerInfo.StartInterestReception();var(i,h)=FakeStream();Queue(i,"1","a","join:");Drain();StreamerInfo.DisconnectInternal();Check(h.Disposed&&StreamerInfo.Interests.Count==0&&StreamerInfo.RecentComments.Count==0&&!StreamerInfo.Interests.Accepting);});
RunLobbyExitTests();StreamerInfo.DisconnectInternal();}
}
